236	/// Actions that are blocked on another internal action of the guest, such as a pipe communication,
237	/// or are blocked on external conditions such as a network request.  These cannot consume a logical
238	/// turn until a matching unblocking action is ready.
239	///
240	/// This structure will NOT include blocking operations that are implemented via polling.
241	/// See NOTE [Blocking Syscalls via Internal Polling] in this folder.
242	#[derive(Debug, Clone, Default)]
243	pub struct BlockedPool {
244	    /// BLOCKED futex transactions, waiting for wakers. Multiple threads may be blocked on
245	    /// the same futex.
246	    ///
247	    /// INVARIANT: because Futexes aren't currently modeled with `ResourceID`, a thread
248	    /// waiting on a futex will have a request filled in `next_turns` but for zero resources.
249	    pub futex_waiters: HashMap<FutexID, Vec<FutexWaiter>>,
250	
251	    /// Futex waiters whose deadlines expired and must receive `ETIMEDOUT` when scheduled.
252	    /// Timed-out waiters are removed from `futex_waiters` before entering the run queue.
253	    pub timed_out_futex_waiters: HashSet<DetTid>,
254	
255	    /// Threads whose next event is waiting on a point in time to proceed.
256	    ///
257	    /// This is sorted by soonest time of occurrence.
258	    /// NOTE: futex waiters will ALSO appear in here if they have timeouts.
259	    pub timed_waiters: TimedEvents,
260	
261	    /// Threads parked until a matching child process exits logically.
262	    pub child_waiters: BTreeMap<DetTid, (DetPid, ChildWaitSpec)>,
263	
264	    /// Threads parked between logical process exit and a backend's final
265	    /// physical-exit report.
266	    pub physical_child_waiters: BTreeMap<DetPid, BTreeSet<DetTid>>,
267	
268	    /// Waiters whose deterministic physical-exit handoff is ready to commit.
269	    pub physical_child_ready: BTreeSet<DetTid>,
270	
271	    /// Blockers on external IO that are in the middle of executing (or have finished) and
272	    /// are waiting for permission from the scheduler to resume.
273	    ///
274	    /// The protocol here is that the `(request,response)` pair (in `next_turns`) for
275	    /// threads in `external_io_blockers` will have the request filled in with an
276	    /// `BlockedExternalContinue` request when the thread is past its blocking action and
277	    /// waiting for permission to resume. A failed operation governed by `BlockingVfork` instead
278	    /// reports `VforkFailed`, which follows the same re-admission path after cancelling its
279	    /// barrier. The request will stay empty while the thread is doing the blocking action. This is
280	    /// different than the normal relationship
281	    pub external_io_blockers: BTreeMap<DetTid, ExternalOpId>,
282	
283	    /// Threads executing the real `rt_sigsuspend` outside the runnable set.
284	    /// These retain the kernel's atomic temporary-mask semantics, but unlike
285	    /// arbitrary external IO they cannot complete without a signal.
286	    pub rt_sigsuspend_blockers: BTreeMap<DetTid, ExternalOpId>,
287	
288	    /// Parents parked awaiting deterministic delivery of a host-async `SIGCHLD`.
289	    ///
290	    /// When a guest child process exits, the kernel raises `SIGCHLD` on the
291	    /// parent at a moment decided purely by host timing. If the resulting
292	    /// `InboundSignal` turn is committed as soon as it arrives, its position
293	    /// races whatever guest work was already runnable -- classically a `make -jN`
294	    /// jobserver `pselect6` continuation -- and `--strict --verify` diverges.
295	    ///
296	    /// Instead the parent is parked here, out of the run queue, and re-admitted
297	    /// by `step2e_process_signal_deferred` only once no ordinary (non-poller)
298	    /// guest work remains: the same deterministic-work-first policy that governs
299	    /// `external_io_blockers`. The physical signal has already been delivered by
300	    /// the kernel, so the handler's `wait4`/`waitpid` still reaps a real host
301	    /// zombie and no synthetic signal is ever generated.
302	    pub sigchld_deferred: BTreeSet<DetTid>,
303	
304	    /// Deferred `SIGCHLD` parents that `step2e_process_signal_deferred` has
305	    /// re-admitted to the run queue. Their `InboundSignal` turn must now be
306	    /// granted rather than deferred again on the turn the scheduler selects them.
307	    pub sigchld_ready: BTreeSet<DetTid>,
308	}
309	
310	impl BlockedPool {
311	    /// Returns true if there are NO blocked threads waiting outside the run-queue.
312	    fn is_empty(&self) -> bool {
313	        self.no_futex_waiters()
314	            && self.timed_waiters.is_empty()
315	            && self.child_waiters.is_empty()
316	            && self.physical_child_waiters.is_empty()
317	            && self.physical_child_ready.is_empty()
318	            && self.external_io_blockers.is_empty()
319	            && self.rt_sigsuspend_blockers.is_empty()
320	            && self.sigchld_deferred.is_empty()
321	    }
322	
323	    /// True if there are no runnable threads, and the only blocked ones are externally-blocked.
324	    fn only_external_blocked(&self) -> bool {
325	        let has_external_wait = !self.external_io_blockers.is_empty()
326	            || !self.child_waiters.is_empty()
327	            || !self.physical_child_waiters.is_empty();
328	        self.no_futex_waiters()
329	            && self.timed_waiters.is_empty()
330	            && self.physical_child_ready.is_empty()
331	            && (has_external_wait || !self.rt_sigsuspend_blockers.is_empty())
332	    }
333	
334	    /// Returns true if there are zero threads blocked on futexes.
335	    fn no_futex_waiters(&self) -> bool {
336	        self.futex_waiters.iter().all(|(_, v)| v.is_empty())
337	    }
338	}
339	
340	/// Validate a request made by a thread executing outside the runnable set.
341	/// A signal may interrupt a real blocking syscall before its ordinary
342	/// continuation request is posted, so an inbound-signal request is ready too.
343	/// `vfork` is excluded because a signal does not satisfy its child barrier.
344	fn blocking_request_is_ready(
345	    req: &Resources,
346	    expected: ExternalOpId,
347	    signal_can_complete: bool,
348	) -> bool {
349	    assert_eq!(req.resources.len(), 1);
350	    let rsrc = req.resources.iter().next().unwrap().0;
351	    match rsrc {
352	        ResourceID::BlockedExternalContinue(op_id) | ResourceID::VforkFailed(op_id) => {
353	            assert_eq!(*op_id, expected);
354	            true
355	        }
356	        ResourceID::InboundSignal(_) if signal_can_complete => true,
357	        other => panic!("expected external continue request, got {other:?}"),
358	    }
359	}
360	
361	/// Runtime state for enforcing a [`HappensBeforeProgram`] inside the scheduler.
362	///
363	/// The scheduler holds each edge's AFTER anchor -- removing that thread from the
364	/// run queue -- until the edge's BEFORE anchor has *fired*, so an authored
365	/// partial order deterministically reproduces a known race instead of relying on
366	/// a seed lottery. An anchor "fires" when its thread is granted passage past the
367	/// corresponding checkpoint (see [`Scheduler::hb_checkpoint`]).
368	///
369	/// Only [`Position::SyscallCount`] anchors are enforced in this milestone. Other
370	/// position kinds are retained for diagnostics but never fire; [`HbRuntime::new`]
371	/// warns about them so a run never silently ignores an ordering constraint.
372	#[derive(Debug)]
373	struct HbRuntime {
374	    /// The validated, normalized program (anchors indexed by name, plus edges).
375	    program: HappensBeforeProgram,
376	    /// Names of anchors that have fired. Monotonic: an anchor fires at most once,
377	    /// when its thread is first granted passage past it.
378	    fired: BTreeSet<String>,
379	    /// Threads currently parked at an AFTER anchor, out of the run queue, awaiting
380	    /// their gating BEFORE anchor(s). A `BTreeSet` keeps re-admission order
381	    /// deterministic.
382	    parked: BTreeSet<DetTid>,
383	    /// Threads observed at creation time, in deterministic spawn order, so an
384	    /// anchor addressed by `spawn_ordinal` resolves to a concrete `DetTid`.
385	    /// Index 0 is the root thread; index N (1-based) is the Nth spawned child,
386	    /// matching [`ThreadRef::spawn_ordinal`] semantics.
387	    spawn_order: Vec<DetTid>,
388	    /// Set when a newly fired anchor may have opened a parked thread's gate, so
389	    /// [`Scheduler::hb_flush_wakes`] re-admits parked threads at the next
390	    /// `step3` boundary. Re-admission is *deferred* to that boundary because it
391	    /// pushes to the run queue, which is illegal while a `tentative_pop`
392	    /// selection is in progress (as it is inside `block_for_one_resource`,
393	    /// where anchors fire).
394	    wake_pending: bool,
395	}
396	
397	impl HbRuntime {
398	    /// Build runtime state from a normalized program, warning about any anchor
399	    /// whose position kind this milestone does not enforce.
400	    fn new(program: HappensBeforeProgram) -> Self {

