1810	    /// Handle a happens-before checkpoint issued by `dettid` after its `count`th
1811	    /// intercepted syscall (see `Detcore::handle_syscall_event`).
1812	    ///
1813	    /// Grants passage (firing every anchor at `SyscallCount(count)` on this
1814	    /// thread and re-admitting any parked threads whose gate may now be open)
1815	    /// unless a reached anchor is the AFTER endpoint of a Hard edge whose BEFORE
1816	    /// anchor has not fired, in which case the thread is parked out of the run
1817	    /// queue until a later firing wakes it. Mirrors the `SleepUntil` park/skip
1818	    /// protocol: the request/response ivars are left intact so the re-admitted
1819	    /// thread re-evaluates this same checkpoint on its next turn.
1820	    fn hb_checkpoint(&mut self, dettid: DetTid, count: u64) -> Result<(), SkipTurn> {
1821	        let (reached, blocked) = {
1822	            let hb = self
1823	                .happens_before
1824	                .as_ref()
1825	                .expect("hb checkpoint issued without a happens-before program");
1826	            let reached = hb.anchors_at_syscall(dettid, count);
1827	            let blocked = reached.iter().any(|name| hb.anchor_blocked(name));
1828	            (reached, blocked)
1829	        };
1830	
1831	        if reached.is_empty() {
1832	            // No anchor addresses this (thread, count); nothing to gate or fire.
1833	            return Ok(());
1834	        }
1835	
1836	        if blocked {
1837	            info!(
1838	                "[scheduler] >>>>>>>\n\n NONCOMMIT turn {}, SKIP dettid {} held at happens-before \
1839	                 anchor(s) {:?} (syscall count {}) awaiting a BEFORE anchor",
1840	                self.turn, dettid, reached, count
1841	            );
1842	            self.happens_before.as_mut().unwrap().parked.insert(dettid);
1843	            return self.skip_turn_blocked(dettid);
1844	        }
1845	
1846	        // Grant passage: fire the reached anchors. Only wake parked threads when a
1847	        // new anchor actually fired, so an idempotent re-grant causes no churn.
1848	        let mut newly_fired = false;
1849	        {
1850	            let hb = self.happens_before.as_mut().unwrap();
1851	            for name in &reached {
1852	                if hb.fired.insert(name.clone()) {
1853	                    newly_fired = true;
1854	                }
1855	            }
1856	        }
1857	        if newly_fired {
1858	            debug!(
1859	                "[happens-before] dettid {} fired anchor(s) {:?} at syscall count {}",
1860	                dettid, reached, count
1861	            );
1862	            // Defer the actual re-admission: we are inside `block_for_one_resource`
1863	            // with a `tentative_pop` selection live, and pushing to the run queue
1864	            // now would trip the queue's transaction assertion. `step3` flushes.
1865	            self.happens_before.as_mut().unwrap().wake_pending = true;
1866	        }
1867	        Ok(())
1868	    }
1869	
1870	    /// If a happens-before anchor fired since the last check, re-admit every
1871	    /// parked thread to the run queue so it re-evaluates its gate on its next
1872	    /// turn. Threads still blocked re-park; the request/response ivars are
1873	    /// untouched, so no request needs re-filling. Deterministic: parked threads
1874	    /// are iterated in `DetTid` order.
1875	    ///
1876	    /// Called from `step3_peek` *before* the turn's `tentative_pop`, the only
1877	    /// safe point to push to the run queue: anchors fire deep inside
1878	    /// `block_for_one_resource` while a selection transaction is live, so the
1879	    /// actual re-admission must be deferred to here.
1880	    fn hb_flush_wakes(&mut self) {
1881	        match self.happens_before.as_mut() {
1882	            Some(hb) if hb.wake_pending => hb.wake_pending = false,
1883	            _ => return,
1884	        }
1885	        let parked: Vec<DetTid> = self
1886	            .happens_before
1887	            .as_ref()
1888	            .map(|hb| hb.parked.iter().copied().collect())
1889	            .unwrap_or_default();
1890	        for dettid in parked {
1891	            self.happens_before.as_mut().unwrap().parked.remove(&dettid);
1892	            if !self.run_queue.contains_tid(dettid) {
1893	                let pos = self.runqueue_push_back(dettid);
1894	                trace!(
1895	                    "[happens-before] re-admitting parked dettid {} at queue position {}",
1896	                    dettid, pos
1897	                );
1898	            }
1899	        }
1900	    }
