1902	    /// Fill in a resource request, which is exactly what might make the next logical
1903	    /// step become unblocked.
1904	    pub fn request_put(
1905	        &mut self,
1906	        req: &Ivar<SchedRequest>,
1907	        rs: Resources,
1908	        _global_time: &Arc<Mutex<GlobalTime>>,
1909	    ) {
1910	        // AUTONOMOUS-BOT-IMPLEMENTED
1911	        // TODO-HUMAN-REVIEW(PR-1041): A guest resource-request RPC can race an
1912	        // asynchronous signal delivery. `force_unblock_thread` replaces
1913	        // `next_turns[tid].req` with an already-full Ivar carrying an
1914	        // `InboundSignal` request (see the `Ivar::full` at the bottom of this
1915	        // file). If the guest's own resource-request then lands on that same
1916	        // turn, the previous unconditional `req.put()` panicked with "Ivar
1917	        // multiple put" (observed intermittently on `timeout 5 echo hi` under
1918	        // `--strict --verify`, where a 5s SIGALRM races the child's `wait4`).
1919	        // Tolerate exactly that case: drop the late guest request and let the
1920	        // signal turn win — the interrupted syscall (e.g. `rt_sigsuspend`)
1921	        // restarts and re-issues a fresh request on the next turn. Any other
1922	        // double-put still panics, preserving the write-once Ivar invariant.
1923	        // Mirrors the `try_put` guard in `logically_kill_thread` (PR-845).
1924	        if let Some(dropped) = req.try_put(Ok(rs)) {
1925	            let tolerated = matches!(
1926	                req.try_read(),
1927	                Some(Ok(existing))
1928	                    if existing
1929	                        .resources
1930	                        .keys()
1931	                        .any(|r| {
1932	                            matches!(
1933	                                r,
1934	                                ResourceID::InboundSignal(_) | ResourceID::WaitidSignals(_)
1935	                            )
1936	                        })
1937	            );
1938	            if tolerated {
1939	                trace!(
1940	                    "[request_put] dropping late guest request {:?}; an async inbound signal already filled the request for this turn (req {})",
1941	                    dropped, req
1942	                );
1943	            } else {
1944	                panic!(
1945	                    "Ivar multiple put exception in request_put! Attempted to write {:?} to {}; existing content is not an inbound-signal request.",
1946	                    dropped, req
1947	                );
1948	            }
1949	        }
1950	    }
