1968	    /// Returns None if all are parked, otherwise the unfilled request of the next we're waiting on.
1969	    fn are_all_quiesced(&self) -> Option<Ivar<SchedRequest>> {
1970	        // Skip raw TIDs whose old run-queue incarnation is pending removal.
1971	        // `Retire` targets have no `next_turns` entry, while
1972	        // `ReplaceThenAdmit` targets have a fresh registration that must not be
1973	        // waited on until the drain removes the old physical slot and admits
1974	        // that replacement.
1975	        self.run_queue
1976	            .tids()
1977	            .filter(|dt| !self.pending_run_queue_removals.contains_key(dt))
1978	            .find_map(|dt| self.check_request(dt))
