2016	    /// Verify that the event we're replaying matches what just happened.  Set up the next
2017	    /// (replayed) event to run.  Return true if the current thread will keep running and false if
2018	    /// it needs to be descheduled.
2019	    ///
2020	    /// PreReq: we're running under --replay-schedule-from
2021	    pub fn consume_schedevent(&mut self, observed: &SchedEvent) -> ConsumeResult {
2022	        debug_assert!(self.replayer.is_some());
2023	        let mytid = observed.dettid;
2024	
2025	        if let Some((ix, action)) = self.replayer.as_mut().map(|r| {
2026	            let current_ix = r.traced_event_count;
2027	            (current_ix, r.observe_event(observed))
2028	        }) {
2029	            let print_stack = self.try_pop_stacktrace_event(ix, observed);
2030	            debug!("Next ReplayAction = {:?}", action);
2031	
2032	            match action {
2033	                replayer::ReplayAction::Continue(timeslice_remaining) => {
2034	                    return ConsumeResult {
2035	                        keep_running: true,
2036	                        print_stack,
2037	                        event_ix: ix,
2038	                        timeslice_remaining,
2039	                    };
2040	                }
2041	                replayer::ReplayAction::Stop(StopReason::FatalDesync) => immediate_fatal_exit(),
2042	                replayer::ReplayAction::Stop(StopReason::ReplayExausted) => immediate_fatal_exit(),
2043	                replayer::ReplayAction::ContextSwitch(is_now, new_tid, timeslice_remaining) => {
2044	                    self.requeue_with_new_priority(mytid, REPLAY_DEFERRED_PRIORITY);
2045	                    self.requeue_with_new_priority(new_tid, REPLAY_FOREGROUND_PRIORITY);
2046	                    if !self.run_queue.contains_tid(new_tid) {
2047	                        // If it is not yet in next_turns, that is because it was JUST spawned and
2048	                        // hasn't showed up yet, but it will by the next scheduler turn.
2049	                        if self.next_turns.contains_key(&new_tid) {
2050	                            tracing::warn!(
2051	                                "Attempted to context switch to tid {}, but it is not runnable atm. This could be legitimate if it is awoken by another thread exiting (futex wake).",
2052	                                new_tid
2053	                            );
2054	                            // TODO(T138906107): make this a fatal error when RESYNC capability is robust enough.
2055	                            // immediate_fatal_exit();
2056	                        }
2057	                    }
2058	                    self.timeslices.insert(new_tid, timeslice_remaining);
2059	                    return ConsumeResult {
2060	                        keep_running: !is_now,
2061	                        print_stack,
2062	                        event_ix: ix,
2063	                        timeslice_remaining,
2064	                    };
2065	                }
2066	            };
2067	        }
2068	
2069	        ConsumeResult {
2070	            keep_running: true,
2071	            print_stack: None,
2072	            event_ix: 0,
2073	            timeslice_remaining: None,
2074	        }
2075	    }
