2165	    /// Apply Linux's successful-exec rule when a backend reloads its tool.
2166	    ///
2167	    /// Every sibling disappears. If a non-leader called exec, Linux also changes
2168	    /// that surviving task's TID to the process leader's TID. In that case the old
2169	    /// caller registration is retired and a fresh leader registration is installed
2170	    /// before it is removed, so process-exit barriers cannot observe a transiently
2171	    /// empty thread group.
2172	    pub fn reconnect_after_exec(&mut self, reconnect: ExecReconnect) -> Vec<DetTid> {
2173	        let ExecReconnect {
2174	            caller,
2175	            new_leader,
2176	            detpid,
2177	            pre_exec_mm,
2178	            post_exec_mm,
2179	            child_tid_addr,
2180	            reconnect_priority,
2181	        } = reconnect;
2182	        let group = self.thread_tree.my_thread_group(&detpid);
2183	        assert!(group.contains(&caller));
2184	        assert!(group.contains(&new_leader));
2185	        self.exec_incarnations.insert(new_leader, post_exec_mm);
2186	
2187	        if caller == new_leader {
2188	            self.next_turns
2189	                .get_mut(&caller)
2190	                .expect("exec caller must retain a scheduler registration")
2191	                .child_tid_addr = child_tid_addr;
2192	
2193	            let siblings: Vec<_> = group.into_iter().filter(|tid| *tid != caller).collect();
2194	            for sibling in &siblings {
2195	                self.logically_kill_thread(sibling, &detpid, pre_exec_mm);
2196	                self.timeslices.remove(sibling);
2197	            }
2198	            self.remove_exec_vfork_barriers(&siblings);
2199	            return siblings;
2200	        }
2201	
2202	        let survivor_priority = self
2203	            .priorities
2204	            .get(&caller)
2205	            .copied()
2206	            .or(reconnect_priority)
2207	            .expect("exec caller must have a scheduler priority");
2208	        let mut retired = Vec::new();
2209	        for old_tid in group.into_iter().filter(|tid| *tid != caller) {
2210	            self.logically_kill_thread(&old_tid, &detpid, pre_exec_mm);
2211	            self.timeslices.remove(&old_tid);
2212	            retired.push(old_tid);
2213	        }
2214	
2215	        // The leader identity was occupied by a thread the kernel destroyed as
2216	        // part of this exec. This is the one intentional exception to permanent
2217	        // raw-TID tombstones: the pending exec record proves why Linux reused it.
2218	        self.logically_killed_threads.remove(&new_leader);
2219	        self.deregistration_accounted.remove(&new_leader);
2220	        self.pending_physical_process_exits.remove(&detpid);
2221	        assert!(
2222	            self.next_turns
2223	                .insert(
2224	                    new_leader,
2225	                    ThreadNextTurn {
2226	                        dettid: new_leader,
2227	                        child_tid_addr,
2228	                        req: Ivar::new(),
2229	                        resp: Ivar::new(),
2230	                        protocol: Default::default(),
2231	                    },
2232	                )
2233	                .is_none(),
2234	            "retired exec leader still had a scheduler registration"
2235	        );
2236	        self.priorities.insert(new_leader, survivor_priority);
2237	        if let Some(writer) = &mut self.preemption_writer {
2238	            writer.set_current(new_leader, survivor_priority);
2239	        }
2240	        // Post-exec reconnection can arrive asynchronously on backends whose
2241	        // exec-child self-bootstraps outside a scheduler turn (DBT), so route
2242	        // the new leader's admission (a run-queue *push*) through the
2243	        // tentative-safe buffer rather than pushing directly.
2244	        //
2245	        // The exec caller's fresh next-turn request is the causal anchor. Step5
2246	        // installed that empty Ivar before the caller began executing exec, so
2247	        // the daemon cannot pass step1 while the successful exec is in flight.
2248	        // This handler records the complete old-leader removal/replacement
2249	        // admission pair before `logically_kill_thread(caller)` resolves that
2250	        // request. The scheduler mutex then prevents step2 from observing only
2251	        // half of the handoff. Host delay can move the handler relative to the
2252	        // daemon's wait, but cannot change first-drain membership.
2253	        //
2254	        // The *removals* in this handler (`logically_kill_thread` ->
2255	        // `run_queue.remove_tid`, for the exec caller and its siblings, above
2256	        // and below) are likewise tentative-safe: `logically_kill_thread` now
2257	        // routes the run-queue removal through `deschedule_or_defer`, which
2258	        // buffers it to the same deterministic `step2` drain. The old leader's
2259	        // removal is explicitly classified as `ReplaceThenAdmit`, so the drain
2260	        // removes its physical queue slot without cancelling the new
2261	        // incarnation. `are_all_quiesced` filters every pending removal key;
2262	        // ordinary targets are logically dead, while the replacement key is not
2263	        // runnable until that old slot has been removed and its admission
2264	        // applied. No handler mutates the queue inside a tentative window.
2265	        self.replace_retired_run_queue_incarnation(new_leader, AdmitIntent::Fixed(AdmitSide::Back));
