2267	
2268	        self.logically_kill_thread(&caller, &detpid, pre_exec_mm);
2269	        self.timeslices.remove(&caller);
2270	        retired.push(caller);
2271	        self.remove_exec_vfork_barriers(&retired);
2272	        retired
2273	    }
