2444	    /// Put a Futex waiter to sleep, to be awoken by `wake_futex_waiter`.
2445	    pub fn sleep_futex_waiter(
2446	        &mut self,
2447	        dettid: &DetTid,
2448	        futexid: FutexID,
2449	        maybe_timeout: Option<LogicalTime>,
2450	        bitset: u32,
2451	    ) {
2452	        let nxt = self
2453	            .next_turns
2454	            .get(dettid)
2455	            .expect("Missing next_turns entry");
2456	        let entry: &mut Vec<_> = self.blocked.futex_waiters.entry(futexid).or_default();
2457	        entry.push(FutexWaiter {
2458	            dettid: *dettid,
2459	            response: nxt.resp.clone(),
2460	            bitset,
2461	        });
2462	        // When we park, we use a resource request to signal WHAT we're blocking on.  But this is
2463	        // not quite the same as when an active thread in the runqueue blocks on a resource, because
2464	        // we're not actually waiting on the scheduler giving us the resource.  We're waiting in the
2465	        // futex_waiters pool until a waker comes along.
2466	        let mut rsrc = Resources::new(*dettid);
2467	        rsrc.insert(ResourceID::FutexWait, Permission::R);
2468	        nxt.req.put(Ok(rsrc));
2469	        trace!(
2470	            "[dtid {}] Waiter blocking on futex {:?}, now {} waiters, on {}",
2471	            &dettid,
2472	            &futexid,
2473	            entry.len(),
2474	            nxt.resp,
2475	        );
2476	        // A futex with timeout waits in both the futex_waiters and timed_events structures:
2477	        if let Some(target_time) = maybe_timeout {
2478	            self.blocked.timed_waiters.insert(target_time, *dettid);
2479	        }
2480	    }
