2482	    /// Reschedule a single thread that has been blocked on futex.
2483	    pub fn wake_futex_waiter(&mut self, waiter: FutexWaiter) {
2484	        let waiterid = waiter.dettid;
2485	        let waiter_ivar = waiter.response;
2486	        debug_assert!(!self.run_queue.contains_tid(waiterid));
2487	
2488	        // If it was registered as a waiter-with-timeout, remove it:
2489	        self.blocked.timed_waiters.remove(waiterid);
2490	
2491	        // Put the woken thread back into circulation:
2492	        let pos = self.runqueue_push_back(waiterid);
2493	        trace!(
2494	            "[detcore] Woke one thread, dtid: {}, ivar {}, scheduled at position {}",
2495	            &waiterid, &waiter_ivar, pos,
2496	        );
2497	        let nxt = self
2498	            .next_turns
2499	            .get_mut(&waiterid)
2500	            .expect("Thread must have an entry in next_turns");
2501	        assert_futex_request(nxt);
2502	        // N.B. We don't write the response here.  That's for the scheduler to do.
2503	        // But with a place in the queue, and a request filled, this thread
2504	        // is ready to run in normal order.
2505	    }
