3097	            "[dtid {}] make pending signal {} visible to the scheduler.",
3098	            dettid, signal
3099	        );
3100	        // `rt_sigsuspend_blockers` joins `external_io_blockers` here per main's
3101	        // rt_sigsuspend work; both mean the thread is parked outside the
3102	        // scheduler and must await its own continuation.
3103	        let has_external_blocker = self.blocked.external_io_blockers.contains_key(&dettid)
3104	            || self.blocked.rt_sigsuspend_blockers.contains_key(&dettid);
3105	        let await_external_continuation =
3106	            self.backend_reports_physical_process_exits && has_external_blocker;
3107	        if cfg!(debug_assertions) && !await_external_continuation {
3108	            let nxtturn = self
3109	                .next_turns
3110	                .get(&dettid)
3111	                .expect("internal invariant broken");
3112	            assert!(
3113	                nxtturn.req.try_read().is_some(),
3114	                "signal_guest: thread should be parked in the scheduler"
3115	            );
3116	        }
3117	        if await_external_continuation {
3118	            return;
3119	        }
