3122	        match self.thread_status(dettid) {
3123	            ThreadStatus::Gone => {
3124	                panic!(
3125	                    "signal_guest: should not have just delivered a signal to a nonexistent thread..."
3126	                );
3127	            }
3128	            ThreadStatus::Running => {
3129	                let is_internal_io_polling = self
3130	                    .next_turns
3131	                    .get(&dettid)
3132	                    .and_then(|next_turn| next_turn.req.try_read())
3133	                    .is_some_and(|request| {
3134	                        request.is_ok_and(|resources| {
3135	                            resources
3136	                                .resources
3137	                                .contains_key(&ResourceID::InternalIOPolling)
3138	                        })
3139	                    });
