3205	    fn restartable_internal_io_signals(&self, dettid: DetTid) -> Option<Vec<SigWrapper>> {
3206	        if !self.backend_supports_parked_write_signal_interruption {
3207	            return None;
3208	        }
3209	        self.next_turns
3210	            .get(&dettid)
3211	            .and_then(|next_turn| next_turn.req.try_read())
3212	            .and_then(Result::ok)
3213	            .and_then(|resources| {
3214	                if resources.resources.len() != 1
3215	                    || resources.signal_interrupt_errno() != Some(Errno::ERESTARTSYS.into_raw())
3216	                {
3217	                    return None;
3218	                }
3219	                match resources.resources.keys().next() {
3220	                    Some(ResourceID::InternalIOPolling) => Some(Vec::new()),
3221	                    Some(ResourceID::WaitidSignals(signals)) => Some(signals.clone()),
3222	                    _ => None,
