3242	    // Force a thread out blocking and into the runnable state, replacing its resource request.
3243	    fn force_unblock_thread(&mut self, dettid: DetTid, rsrcs: Resources) {
3244	        info!(
3245	            "[dtid {}] removing blocking entries and requeuing thread",
3246	            dettid
3247	        );
3248	        self.remove_blocking_entries(&dettid);
3249	
3250	        if let Some(nxt) = self.next_turns.get_mut(&dettid) {
3251	            // Counterfeit the entry as though the thread had requested this resource from the start:
3252	            nxt.req = Ivar::full(Ok(rsrcs));
3253	        }
