3255	        // Targeted chaos (T137242449): a force-unblocked thread (e.g. woken by a
3256	        // signal or ready I/O) is normally requeued at the back of its priority
3257	        // level, so it runs after everything already queued. Randomizing whether
3258	        // it jumps to the front instead varies the order in which a just-woken
3259	        // thread races the threads it was contending with -- surfacing
3260	        // lock-ordering / wakeup-ordering races. Reproducible under `--fuzz-seed`.
3261	        let to_front = self.chaos_target_races
3262	            && chaos_pick(&mut self.fuzz_prng, &[true, false]).unwrap_or(false);
3263	        if to_front {
3264	            self.runqueue_push_front(dettid);
3265	        } else {
3266	            self.runqueue_push_back(dettid);
3267	        }
3268	    }
