3270	    /// Check on threads executing blocking syscalls outside the runnable set.
3271	    fn step2c_process_io_blockers(&mut self) -> Result<(), SkipTurn> {
3272	        if !self.blocked.external_io_blockers.is_empty()
3273	            || !self.blocked.rt_sigsuspend_blockers.is_empty()
3274	        {
3275	            // A nondeterministic snapshot of which backgrounded actions are ready right now:
3276	            let mut blockers: Vec<(DetTid, ExternalOpId, bool)> = self
3277	                .blocked
3278	                .external_io_blockers
3279	                .iter()
3280	                .map(|(dtid, op_id)| (*dtid, *op_id, !self.vfork_barriers.contains_key(dtid)))
3281	                .chain(
3282	                    self.blocked
3283	                        .rt_sigsuspend_blockers
3284	                        .iter()
3285	                        .map(|(dtid, op_id)| (*dtid, *op_id, true)),
3286	                )
3287	                .collect();
3288	            blockers.sort_by_key(|(dtid, _, _)| *dtid);
3289	            let ready: Vec<DetTid> = blockers
3290	                .iter()
3291	                .filter(|(dtid, op_id, signal_can_complete)| {
3292	                    let nt = self
3293	                        .next_turns
3294	                        .get(dtid)
3295	                        .expect("internal invariant broken");
3296	                    if let Some(Ok(req)) = nt.req.try_read() {
3297	                        blocking_request_is_ready(&req, *op_id, *signal_can_complete)
3298	                    } else {
3299	                        false
3300	                    }
3301	                })
3302	                .map(|(dtid, _, _)| *dtid)
3303	                .collect();
3304	            debug!(
3305	                "Nondeterministic status of backgrounded operations: out of {}, completed on {}, dtids: {:?}",
3306	                blockers.len(),
3307	                ready.len(),
3308	                ready
3309	            );
3310	
3311	            let requeue_ready = |scheduler: &mut Self, ready: &[DetTid]| {
3312	                for ready_dtid in ready {
3313	                    info!(
3314	                        "[step2] Reschedule formerly backgrounded dtid {:?}",
3315	                        ready_dtid
3316	                    );
3317	                    let external = scheduler.blocked.external_io_blockers.remove(ready_dtid);
3318	                    let sigsuspend = scheduler.blocked.rt_sigsuspend_blockers.remove(ready_dtid);
3319	                    assert!(
3320	                        external.is_some() ^ sigsuspend.is_some(),
3321	                        "ready thread must belong to exactly one blocking pool"
3322	                    );
3323	                    scheduler.run_queue.push_eager_io_repoll(*ready_dtid);
3324	                }
3325	            };
3326	
3327	            // FIXME TODO (T137183027): for record/replay to work properly, we need to ALLOW the
3328	            // "Nondeterminstic algorithm" below, but record & replay those scheduler events. In
3329	            // the meantime, use a deterministic eager policy once there is no other runnable work.
3330	            if self.recordreplay_modes {
