3420	    /// Render one blocked thread's pending request, with a stable resource order.
3421	    ///
3422	    /// `Resources::resources` is a `HashMap`, so its iteration order is not
3423	    /// reproducible; sort the rendered entries. Reads the `Ivar`'s contents
3424	    /// rather than `Debug`-printing the `Ivar`, whose parked `Waker` carries raw
3425	    /// host pointers.
3426	    fn render_pending_request(req: &Ivar<SchedRequest>) -> String {
3427	        match req.try_read() {
3428	            None => "<no request pending>".to_owned(),
3429	            Some(Err(ThreadExited)) => "<thread exited>".to_owned(),
3430	            Some(Ok(rsrc)) => {
3431	                let mut held: Vec<String> = rsrc
3432	                    .resources
3433	                    .iter()
3434	                    .map(|(rid, perm)| match rid {
3435	                        // Spell the sentinel out. Its derived `Debug` is
3436	                        // `SleepUntil(LogicalTime(18446744073709551615))`, and a
3437	                        // reader who has to decode that number by hand is
3438	                        // exactly the reader this report failed.
3439	                        ResourceID::SleepUntil(deadline) if deadline.is_indefinite() => {
3440	                            format!("SleepUntil(INDEFINITE): {:?}", perm)
3441	                        }
3442	                        _ => format!("{:?}: {:?}", rid, perm),
3443	                    })
3444	                    .collect();
3445	                held.sort();
3446	                let mut rendered = if held.is_empty() {
3447	                    "<no resources>".to_owned()
3448	                } else {
3449	                    held.join(", ")
3450	                };
3451	                if rsrc.poll_attempt != 0 {
3452	                    let _ = write!(rendered, " (poll_attempt {})", rsrc.poll_attempt);
3453	                }
3454	                if !rsrc.fyi.is_empty() {
3455	                    let _ = write!(rendered, " (fyi {:?})", rsrc.fyi);
3456	                }
3457	                rendered
3458	            }
3459	        }
3460	    }
