4161	                        self.completed_physical_process_exits.contains(child);
4162	                    assert!(
4163	                        self.blocked
4164	                            .physical_child_waiters
4165	                            .entry(*child)
4166	                            .or_default()
4167	                            .insert(dettid)
4168	                    );
4169	                    let skipped = self.skip_turn_blocked(dettid);
4170	                    if completion_already_observed {
4171	                        self.wake_physical_child_waiters(*child);
4172	                    }
4173	                    skipped
4174	                }
4175	            }
4176	
4177	            // Thread requests change in priority
4178	            ResourceID::PriorityChangePoint(prio, change_time, rcbs, epochs) => {
4179	                self.perform_priority_changepoint(dettid, *prio, *change_time, *rcbs, epochs)
4180	            }
4181	
4182	            // For now, all other resource types are immediately granted.
4183	            // (TODO/FIXME: handle the entire set of resource requests.)
4184	            ResourceID::FileContents(_) => Ok(()),
4185	            ResourceID::FileMetadata(_) => Ok(()),
4186	            ResourceID::DirectoryContents(_) => Ok(()),
4187	            ResourceID::MemAddrSpace(_) => Ok(()),
4188	            ResourceID::Path(_) => Ok(()),
4189	            ResourceID::PathsTransitive(_) => Ok(()),
4190	            ResourceID::Device(_) => Ok(()),
4191	            // The scheduler-ordered `Exit` grant is the deterministic moment a
4192	            // child process leaves the run set. Register a one-shot child-exit
4193	            // `SIGCHLD` for the reaping parent, to be delivered at a deterministic
4194	            // logical time by `step2b_process_timed`, instead of relying on the
4195	            // host-async kernel `SIGCHLD` whose arrival time is host-timed (the
4196	            // `make -jN` / redis `--strict --verify` nondeterminism source).
4197	            // A backend that registered a PIDFD_THREAD already preserves the
4198	            // kernel's native child-exit signal. Sending another SIGCHLD through
4199	            // that pidfd would make the application observe both CLD_EXITED and
4200	            // SI_TKILL for one child, so only the scheduler wait readiness is
4201	            // synthesized on that path.
4202	            ResourceID::Exit { group, process, mm } => {
4203	                let reserve_mode = match self.reserve_exit_boundary(dettid, *process, *mm, *group) {
4204	                    Ok(mode) => mode,
4205	                    Err(failure) => {
4206	                        self.fail_parked(dettid, failure);
4207	                        // fail_parked linearizes terminal failure and closes
4208	                        // the tentative selection. Do not undo it a second
4209	                        // time through skip_turn_blocked.
4210	                        return Err(SkipTurn);
4211	                    }
4212	                };
4213	                if reserve_mode == signal_control::ExitReserveMode::Uncontrolled
4214	                    && *group
4215	                    && let Some(parent) = self.thread_tree.parent_process(process)
4216	                    && self.should_synthesize_child_exit_signal(parent)
4217	                {
4218	                    // Fire strictly after the current committed time so the event
4219	                    // is dispatched on a subsequent scheduler pass (DetTid == DetPid
4220	                    // for a group leader, so `parent` is also the parent thread id).
4221	                    let deadline = self.committed_time + LogicalTime::from_nanos(1);
4222	                    self.blocked
4223	                        .timed_waiters
4224	                        .insert_child_exit(deadline, *process, parent, parent);
4225	                }
4226	                Ok(())
4227	            }
4228	            ResourceID::ParentContinue { .. } => Ok(()),
4229	            ResourceID::InternalIOPolling => Ok(()),
4230	            ResourceID::FutexWait => Ok(()),
4231	            ResourceID::TraceReplay => Ok(()),
4232	            ResourceID::SchedYield => Ok(()),
4233	
4234	            // A guest thread checking in at a happens-before anchor point. Delegate
4235	            // to the enforcement logic, which either grants passage (firing anchors)
4236	            // or parks the thread until its gating BEFORE anchor fires.
4237	            ResourceID::HappensBeforeCheckpoint(count) => self.hb_checkpoint(dettid, *count),
4238	
4239	            // A host-async SIGCHLD (a guest child process exited) is delivered to
4240	            // the parent at a moment decided by host timing. Committing that turn
4241	            // immediately makes the signal race whatever guest work was already
4242	            // runnable (e.g. a `make -jN` jobserver `pselect6` continuation),
4243	            // which diverges under `--strict --verify`. Defer it deterministic-
4244	            // work-first: park the parent out of the run queue and let
4245	            // `step2e_process_signal_deferred` re-admit it once no ordinary guest
4246	            // work remains, mirroring the `external_io_blockers` policy. Signals
4247	            // that the scheduler itself synthesizes deterministically (timers via
4248	            // `fire_alarm`) are never SIGCHLD and are unaffected.
4249	            ResourceID::WaitidSignals(_) => Ok(()),
4250	            ResourceID::InboundSignal(sig) => {
4251	                // `sigchld_ready` marks a parent step2e has already re-admitted;
4252	                // grant it now rather than deferring it a second time.
4253	                let already_readmitted = self.blocked.sigchld_ready.remove(&dettid);
4254	                if sig.signal() == Some(Signal::SIGCHLD)
4255	                    && signal_interrupt_errno.is_none()
4256	                    && !already_readmitted
4257	                    && self.run_queue.has_runnable_besides(dettid)
4258	                {
4259	                    self.run_queue.undo_tentative_pop(); // Begun in step3.
4260	                    assert!(self.run_queue.remove_tid(dettid));
4261	                    self.blocked.sigchld_deferred.insert(dettid);
4262	                    Err(SkipTurn)
4263	                } else {
4264	                    Ok(())
4265	                }
4266	            }
4267	        }
4268	    }
