4280	    fn requeue_with_new_priority(&mut self, dettid: DetTid, new_priority: Priority) {
4281	        // TODO: do we want to record in preemption_writer if we are in schedule-trace-replay mode?
4282	        assert!(runqueue::is_ordinary_priority(new_priority));
4283	        // Alter the threads priority and requeue.
4284	        let _old_priority = self.priorities.insert(dettid, new_priority);
4285	        let present = self.run_queue.remove_tid(dettid);
4286	        if present {
4287	            self.runqueue_push_back(dettid); // Repush with new priority
4288	        }
4289	        trace!(
