4295	    /// Helper for priority changepoint logic
4296	    ///
4297	    /// Precondition: guest is stopped so that there is no chance the ivars are being used
4298	    /// concurrently while they are being cleared.
4299	    ///
4300	    /// Postcondition: Same as block_for_one_resource. However, always returns SkipTurn, because the
4301	    /// priority changepoint may not allow the current thread to continue in a regular turn (i.e.
4302	    /// doing actual work).
4303	    fn perform_priority_changepoint(
4304	        &mut self,
4305	        dettid: DetTid,
4306	
4307	        new_priority: Priority,
4308	        guest_time: LogicalTime,
4309	        guest_rcbs: u64,
4310	        // AUTONOMOUS-BOT-IMPLEMENTED
4311	        // TODO-HUMAN-REVIEW(PR-1151)
4312	        chaos_epochs: &[crate::resources::ChaosEpochTransition],
4313	    ) -> Result<(), SkipTurn> {
4314	        assert!(runqueue::is_ordinary_priority(new_priority));
4315	        // Alter the threads priority and requeue.
4316	        let old_priority = self.priorities.insert(dettid, new_priority);
4317	
4318	        // Do not attempt to record preemptions/priorities when we're dictated by a raw schedule replay.
4319	        if self.replayer.is_none()
4320	            && let Some(pw) = &mut self.preemption_writer
4321	        {
4322	            let old_prio = old_priority.unwrap();
4323	            debug!(
4324	                "[dtid {}] Recording preemption point, current time {} prior priority {} (next priority {})",
4325	                dettid, guest_time, old_prio, new_priority
4326	            );
4327	            for transition in chaos_epochs {
4328	                pw.insert_chaos_epoch(dettid, *transition);
4329	            }
4330	            pw.insert_reprioritization(dettid, guest_time, guest_rcbs, old_prio, new_priority);
4331	            pw.set_current(dettid, new_priority);
4332	        }
4333	
4334	        let popped = self.run_queue.commit_tentative_pop(); // Begun in step3.
4335	        assert_eq!(dettid, popped);
4336	        self.runqueue_push_back(dettid); // Repush with new priority
4337	        trace!(
4338	            "[dettid {}] changepoint: Priority mapping after change to priority {}: {:?}",
4339	            dettid, new_priority, self.priorities
4340	        );
4341	
4342	        // Update request to be empty so the thread is unconditionally
4343	        // runnable when it next comes up in the queue.
4344	        let empty_req = Ivar::full(Ok(Resources::new(dettid)));
4345	        trace!(
4346	            "[dettid {}] Priority change point emplaced empty resource request at new {}",
4347	            dettid, empty_req
4348	        );
4349	        self.next_turns
4350	            .get_mut(&dettid)
4351	            .expect("nextturn present")
4352	            .req = empty_req;
4353	        info!(
4354	            "[scheduler] >>>>>>>\n\n NONCOMMIT turn {}, dettid {} changed priority to {}",
4355	            self.turn, dettid, new_priority
4356	        );
4357	        self.skip_turn() // The thread shouldn't run.
4358	    }
