4414	    /// Tick global logical time due to represent the work of the scheduler itself.
4415	    /// Also, update committed time.
4416	    /// Prerequisite: all threads are parked, with their time contributions frozen.
4417	    fn bump_global_time(
4418	        &mut self,
4419	        global_time: &Mutex<GlobalTime>,
4420	        last_turn: &Result<Resources, SkipTurn>,
4421	    ) {
4422	        // An internal IO-polling retry (see `is_polling_turn`) must still advance logical
4423	        // time -- finite poll/epoll/select/futex timeouts are enforced by comparing observed
4424	        // logical time against the deadline in `retry_nonblocking_syscall_helper`, so freezing
4425	        // time here would turn a timed wait into an infinite spin. But because the *count* of
4426	        // these retries is host-timing nondeterministic, we keep their time-advance out of the
4427	        // determinism log (DETLOG). This makes the `--verify` deterministic comparison
4428	        // insensitive to retry count; the matching `{InternalIOPolling: ...}` COMMIT turn is
4429	        // likewise excluded in `logdiff::is_internal_io_poll_commit`. Time values still shift
4430	        // between runs, but those are numerically normalized before comparison.
4431	        let last_turn_was_polling = last_turn
4432	            .as_ref()
4433	            .map(|resources| {
4434	                Self::is_polling_turn(resources)
4435	                    || self.is_sabre_internal_pipe_io_turn(resources)
4436	                    || self.is_sabre_loopback_poll_yield_turn(resources)
4437	            })
4438	            .unwrap_or(false);
4439	
4440	        // At this moment, when threads are parked, we know that the global_time is
4441	        // frozen and we can read it without any race.
4442	        let snapshot: LogicalTime = {
4443	            let mut gtime = global_time.lock().unwrap();
4444	
4445	            if self.run_queue.is_empty() && self.blocked.only_external_blocked() {
4446	                // TODO(T112017687): rationalize the occurence of
4447	                // BlockingExternalIO in strict runs. For example, we should
4448	                // probably inject nanosleep and actually wait the intervening
4449	                // time, so we don't appear too fast to external observers.
4450	                trace!(
4451	                    "[scheduler] skipping scheduler time advance because we're ONLY waiting for external events"
4452	                );
4453	            } else if last_turn.is_err() {
4454	                // Note: if the last turn was a skip, it shouldn't really have time-bumped. But since we
4455	                // can't see the future, we just cancel out the bump by not doing a bump this turn.
4456	                trace!(
4457	                    "[scheduler] skipping scheduler time advance because just-finished turn did not progress (i.e. SkipTurn)"
4458	                );
4459	            } else if last_turn
4460	                .as_ref()
4461	                .map(Self::is_internal_turn)
4462	                .unwrap_or(false)
4463	            {
4464	                trace!(
4465	                    "[scheduler] skipping scheduler time advance because just-finished turn was an internal book-keeping one"
4466	                );
4467	            } else {
4468	                let newtime = gtime.add_scheduler_time();
4469	                if last_turn_was_polling {
4470	                    // Advance time (needed for timeout enforcement) but keep it off the DETLOG.
4471	                    trace!(
4472	                        "[sched] advance global time for internal IO-polling retry (suppressed from detlog), new time {:?}",
4473	                        newtime,
4474	                    );
4475	                } else {
4476	                    detlog_debug!(
4477	                        "[sched] advance global time for scheduler turn, new time {:?}",
4478	                        newtime,
4479	                    );
4480	                }
4481	            }
4482	            gtime.as_nanos()
4483	        };
4484	
4485	        match snapshot.cmp(&self.committed_time) {
4486	            std::cmp::Ordering::Less => {
4487	                panic!(
4488	                    "bump_global_time: invariant broken, global time went backwards from {} to {}",
4489	                    self.committed_time, snapshot
4490	                );
4491	            }
4492	            std::cmp::Ordering::Equal => {}
4493	            std::cmp::Ordering::Greater => {
4494	                // NB: `committed_time` still tracks the (host-timing-perturbed) global clock,
4495	                // including the time advanced by suppressed IO-polling retries above, so this
4496	                // line's presence is retry-count sensitive. It is therefore excluded from the
4497	                // deterministic `--verify` comparison in `logdiff::is_scheduler_committed_time`
4498	                // (it is redundant with the per-turn "advance global time" DETLOG anyway).
4499	                detlog_debug!(
4500	                    event = crate::detlog::DetLogEvent::SchedulerCommittedTime;
4501	                    "[sched-step1] advancing committed_time from {} to {}",
4502	                    self.committed_time,
4503	                    snapshot
4504	                );
4505	                self.committed_time = snapshot;
4506	            }
4507	        }
4508	    }
