4510	    /// Step 4: unblock enabled actions to actually, physically run.
4511	    fn step5_guest_unblock(
4512	        &mut self,
4513	        next_dtid: DetTid,
4514	        rsrcs: &Resources,
4515	        resp: &Ivar<SchedResponse>,
4516	    ) -> Result<(), SkipTurn> {
4517	        match self.next_turns.get(&next_dtid) {
4518	            None => {
4519	                info!(
4520	                    "Scheduler was about to schedule {} for a turn (resources {:?}), but it died first.",
4521	                    &next_dtid, rsrcs.resources
4522	                );
4523	                Err(SkipTurn)
4524	            }
4525	            Some(nxt) => {
4526	                assert_eq!(resp, &nxt.resp);
4527	                // Refuse an exhausted transport identity before recording a
4528	                // COMMIT or consuming any response state.
4529	                if nxt.protocol.epoch.checked_add(1).is_none() {
4530	                    self.fail_parked(next_dtid, parked::ProtocolFailure::Overflow);
4531	                    return Err(SkipTurn);
