4533	                // N.B.: these prints themselves should be deterministic between
4534	                // runs.  They are part of the "detlog".
4535	                let normalization_marker = if self.is_sabre_internal_pipe_io_turn(rsrcs) {
4536	                    " [sabre-internal-pipe-io]"
4537	                } else if self.is_sabre_loopback_poll_yield_turn(rsrcs) {
4538	                    " [sabre-loopback-poll-zero-timeout]"
4539	                } else {
4540	                    ""
4541	                };
4542	                if enabled!(Level::INFO) {
