4545	                            || self.is_sabre_internal_pipe_io_turn(rsrcs)
4546	                            || self.is_sabre_loopback_poll_yield_turn(rsrcs);
4547	                    let runtime_maps_read = rsrcs.resources.keys().any(|resource| {
4548	                        matches!(
4549	                            resource,
4550	                            ResourceID::Path(path)
4551	                                if path.as_path() == std::path::Path::new("/proc/self/maps")
4552	                        )
