4555	                        self.turn,
4556	                        self.committed_time.as_nanos(),
4557	                        internal_io_poll,
4558	                        runtime_maps_read,
4559	                    );
4560	                    info!(
4561	                        "[sched-step5] >>>>>>>\n\n COMMIT turn {}, dettid {} using resources {:?}, on previously committed {}{}{}",
4562	                        self.turn,
4563	                        next_dtid,
4564	                        rsrcs.resources,
4565	                        self.committed_time,
