4576	    /// Unblock the guest to run, clear its ivars for the next turn, and increment the turn counter.
4577	    ///
4578	    /// Precondition: guest is stopped.
4579	    /// Postcondition: guest is running concurrently with this scheduler/tracer thread.
4580	    fn unblock_guest(&mut self, dtid: DetTid, resp: &Ivar<SchedResponse>) -> Result<(), SkipTurn> {
4581	        trace!(
4582	            "[sched-step5] Guest unblocking (via {}); clear ivars for the next turn on dettid {}",
4583	            &resp, &dtid
4584	        );
4585	        let signals = self.inbound_signals(dtid); // Peek before we clear the ivars.
4586	        let futex_timed_out = self.blocked.timed_out_futex_waiters.remove(&dtid);
4587	        if let Err(error) = self.clear_nextturn(dtid) {
4588	            self.fail_parked(dtid, error);
4589	            return Err(SkipTurn);
4590	        }
4591	        self.turn += 1;
4592	        let answer = if !signals.is_empty() {
4593	            SchedResponse::Signaled(Some(signals))
4594	        } else if futex_timed_out {
4595	            SchedResponse::Go(Some(SchedValue::TimeOut))
4596	        } else {
4597	            let timeslice = self.timeslices.remove(&dtid).flatten();
4598	            // TODO(T137799529): use a more strongly typed representation rather than reusing
4599	            // SchedValue/u64:
4600	            let as_schedvalue = timeslice
4601	                .as_ref()
4602	                .map(LogicalTime::as_nanos)
4603	                .map(SchedValue::Value);
4604	            SchedResponse::Go(as_schedvalue)
4605	        };
4606	        self.parked.running = Some(dtid);
4607	        resp.put(answer);
4608	        Ok(())
4609	    }
