4611	    fn inbound_signals(&self, dettid: DetTid) -> Vec<SigWrapper> {
4612	        let req = &self.next_turns.get(&dettid).unwrap().req;
4613	        let mut signals = Vec::new();
4614	        if let Some(Ok(resources)) = req.try_read() {
4615	            for resource in resources.resources.keys() {
4616	                match resource {
4617	                    ResourceID::InboundSignal(signal) => signals.push(*signal),
4618	                    ResourceID::WaitidSignals(batch) => signals.extend(batch.iter().copied()),
4619	                    _ => {}
4620	                }
4621	            }
4622	        }
4623	        // A signal can legitimately appear in both an `InboundSignal` and a
4624	        // merged `WaitidSignals` batch. Sort then dedup so the reported set is a
4625	        // canonical function of WHICH signals are pending, not of how many
4626	        // resources happen to carry each one or of the order they arrived in.
4627	        signals.sort_by_key(|signal| signal.0 as libc::c_int);
4628	        signals.dedup_by_key(|signal| signal.0 as libc::c_int);
4629	        signals
4630	    }
