4632	    /// Clear the thread's nextturn, installing fresh ivars.
4633	    ///
4634	    /// Precondition: guest is stopped so that there is no chance the ivars are being used
4635	    /// concurrently while they are being cleared.
4636	    fn clear_nextturn(&mut self, dtid: DetTid) -> Result<(), parked::ProtocolFailure> {
4637	        let epoch = self
4638	            .next_turns
4639	            .get(&dtid)
4640	            .ok_or(parked::ProtocolFailure::Identity)?
4641	            .protocol
4642	            .epoch
4643	            .checked_add(1)
4644	            .ok_or(parked::ProtocolFailure::Overflow)?;
4645	        self.settle_parked_grant(dtid);
4646	        self.clear_ready_polled_read(dtid);
4647	        let nextturn = self
4648	            .next_turns
4649	            .get_mut(&dtid)
4650	            .expect("clear_nextturn: Thread should be available in next_turns");
4651	        nextturn.req = Ivar::new();
4652	        nextturn.resp = Ivar::new();
4653	        nextturn.protocol.epoch = epoch;
4654	        nextturn.protocol.origin = None;
4655	        Ok(())
4656	    }
