5208	            None
5209	        };
5210	
5211	        let (reprio_descrip, info_reprio_descrip) = if let Some(pw) = self.preemption_writer.take()
5212	        {
5213	            let mut buf = String::new();
5214	            writeln!(
5215	                buf,
5216	                "Record of {} preemption and reprioritization events:",
5217	                pw.len()
5218	            )?;
5219	            let info_description;
5220	            if let Some(path) = preemptions_to {
5221	                // Preserve the full human/JSON description; build the INFO
