5278	    /// Summarize the state of the scheduler while executing (verbose).
5279	    pub fn full_summary(&self) -> String {
5280	        let mut buf = String::new();
5281	        write!(&mut buf, "  {}", self.run_queue).unwrap();
5282	
5283	        let total_futex_blocked: usize = self.blocked.futex_waiters.iter().map(|v| v.1.len()).sum();
5284	        writeln!(
5285	            &mut buf,
5286	            "\n  Futex-waiters, {} blocked on {} futexes:",
5287	            total_futex_blocked,
5288	            self.blocked.futex_waiters.len()
5289	        )
5290	        .unwrap();
5291	        // Sorted, and no `Ivar` Debug. `format_terminal_deadlock` above already
5292	        // documents the two sources this avoids, and this function had neither
5293	        // guard: `futex_waiters` is a `HashMap`, so it iterates in a randomized
5294	        // order once it holds more than one entry, and `FutexWaiter`'s derived
5295	        // `Debug` prints its `Ivar`'s parked waker as raw host pointers.
5296	        //
5297	        // Measured before this change, three runs of
5298	        // `--stop-after-turn=15 -- rustbin_futex_and_print`, which reaches this
5299	        // function through the `--stop-after-turn` warning:
5300	        //   Waker { data: 0x564ea2a82c80
5301	        //   Waker { data: 0x55f2120b9c80
5302	        //   Waker { data: 0x56163deeec80
5303	        // Three runs, three host addresses, in a WARN record that
5304	        // `--verify-strict` compares.
5305	        //
5306	        // Only guest-level identities are printed here: the futex key, the
5307	        // waiting dettid and the bitset are all values Detcore already
5308	        // determinizes.
5309	        let mut futex_rows: Vec<String> = self
5310	            .blocked
5311	            .futex_waiters
5312	            .iter()
5313	            .map(|(futex, waiters)| {
5314	                let mut dettids: Vec<String> =
5315	                    waiters.iter().map(|w| w.dettid.to_string()).collect();
5316	                dettids.sort();
5317	                let mut bitsets: Vec<u32> = waiters.iter().map(|w| w.bitset).collect();
5318	                bitsets.sort_unstable();
5319	                format!(
5320	                    "    {:?} => {} waiter(s), dettids [{}], bitsets {:?}",
5321	                    futex,
5322	                    waiters.len(),
5323	                    dettids.join(", "),
5324	                    bitsets
5325	                )
5326	            })
5327	            .collect();
5328	        futex_rows.sort();
5329	        for row in futex_rows {
5330	            writeln!(&mut buf, "{}", row).unwrap();
5331	        }
5332	
5333	        writeln!(
5334	            &mut buf,
5335	            "\n  Timed-waiters, {}:",
5336	            self.blocked.timed_waiters.len()
5337	        )
5338	        .unwrap();
5339	        for (time, dtid) in self.blocked.timed_waiters.iter() {
5340	            writeln!(&mut buf, "    {} => {}", time, dtid).unwrap();
5341	        }
5342	
5343	        writeln!(
5344	            &mut buf,
5345	            "\n  External-IO-blocked, {}:",
5346	            self.blocked.external_io_blockers.len(),
5347	        )
5348	        .unwrap();
5349	        for x in &self.blocked.external_io_blockers {
5350	            writeln!(&mut buf, "    {:?}", x).unwrap();
5351	        }
5352	
5353	        writeln!(
5354	            &mut buf,
5355	            "\n  Rt-sigsuspend-blocked, {}:",
5356	            self.blocked.rt_sigsuspend_blockers.len(),
5357	        )
5358	        .unwrap();
5359	        for x in &self.blocked.rt_sigsuspend_blockers {
5360	            writeln!(&mut buf, "    {:?}", x).unwrap();
5361	        }
5362	
5363	        writeln!(&mut buf, "\n  Next_turns: ").unwrap();
5364	        for (dtid, nxt) in self.next_turns.iter() {
5365	            writeln!(
5366	                &mut buf,
5367	                " ==> dtid {}, req {}, resp {}",
5368	                dtid, nxt.req, nxt.resp
5369	            )
5370	            .unwrap();
5371	        }
5372	        buf
5373	    }
