5397	    // Returns the logical duration until any previously scheduled alarm, if any (zero otherwise).
5398	    pub fn register_alarm(
5399	        &mut self,
5400	        detpid: DetPid,
5401	        dettid: DetTid,
5402	        now: LogicalTime,
5403	        duration: LogicalTime,
5404	        interval: LogicalTime,
5405	        sig: Signal,
5406	    ) -> (LogicalTime, LogicalTime) {
5407	        let old = if duration == LogicalTime::ZERO {
5408	            // Alarm of 0 cancels any pending signal.
5409	            self.blocked.timed_waiters.remove_alarm(detpid)
5410	        } else {
5411	            let target_time = now + duration;
5412	            self.blocked
5413	                .timed_waiters
5414	                .insert_alarm(target_time, detpid, dettid, sig, interval)
5415	        };
5416	        if let Some((old_target_time, old_interval)) = old {
5417	            let remain_ns = old_target_time.as_nanos().saturating_sub(now.as_nanos());
5418	            (LogicalTime::from_nanos(remain_ns), old_interval)
5419	        } else {
5420	            // Return 0 if no previous alarm, as per https://man7.org/linux/man-pages/man2/alarm.2.html
5421	            (LogicalTime::ZERO, LogicalTime::ZERO)
5422	        }
5423	    }
