5751	    /// F1/F2: an admission deferred while a tentative_pop window is live must
5752	    /// resolve its side -- including the `RunsPostFork::Random` PRNG draw -- at
5753	    /// the `DetTid`-ordered drain, so the drained run queue is a pure function of
5754	    /// deterministic state, independent of the order in which racing handlers
5755	    /// buffered the admissions.
5756	    #[test]
5757	    fn deferred_admission_side_is_arrival_order_independent() {
5758	        let config = Config {
5759	            sched_seed: Some(0xABCD),
5760	            runs_post_fork: RunsPostFork::Random,
5761	            ..Default::default()
5762	        };
5763	        let lower = DetTid::from_raw(21);
5764	        let higher = DetTid::from_raw(23);
5765	
5766	        // Buffer the two children in `order`, optionally while a tentative
5767	        // window is live, then drain. Return the drained relative order of the
5768	        // two children (the anchor is filtered out because it is consumed by the
5769	        // window in the `open_window` case but not otherwise -- what must be
5770	        // deterministic is the children's order and chosen sides).
5771	        let drained_order = |order: [DetTid; 2], open_window: bool| -> Vec<DetTid> {
5772	            let mut sched = Scheduler::new(&config);
5773	            let anchor = DetTid::from_raw(5);
5774	            register_known_thread(&mut sched, anchor);
5775	            sched.runqueue_push_back(anchor);
5776	            register_known_thread(&mut sched, lower);
5777	            register_known_thread(&mut sched, higher);
5778	
5779	            if open_window {
5780	                assert_eq!(sched.run_queue.tentative_pop_next(), Some(anchor));
5781	                assert!(sched.run_queue.tentative_pop_in_progress());
5782	            }
5783	            for tid in order {
5784	                sched.admit_to_run_queue(tid, AdmitIntent::PostFork(RunsPostFork::Random));
5785	            }
5786	            // Admission ALWAYS defers -- window or not -- so nothing is pushed or
5787	            // resolved (no side chosen, no PRNG drawn) until the drain.
5788	            assert!(sched.pending_run_queue_admissions.contains_key(&lower));
5789	            assert!(sched.pending_run_queue_admissions.contains_key(&higher));
5790	            assert!(!sched.run_queue.contains_tid(lower));
5791	            assert!(!sched.run_queue.contains_tid(higher));
5792	
5793	            if open_window {
5794	                let _ = sched.run_queue.commit_tentative_pop();
5795	            }
5796	            sched.drain_pending_run_queue_admissions();
5797	            sched
5798	                .run_queue
5799	                .tids()
5800	                .copied()
5801	                .filter(|t| *t == lower || *t == higher)
5802	                .collect()
5803	        };
5804	
5805	        // The drained order/side is independent of BOTH host-timing inputs the
5806	        // old immediate path was sensitive to: the arrival (buffering) order of
5807	        // the racing handlers, and whether a tentative window happened to be
5808	        // live when each handler ran.
5809	        let baseline = drained_order([lower, higher], true);
5810	        assert_eq!(
5811	            baseline,
5812	            drained_order([higher, lower], true),
5813	            "arrival order"
5814	        );
5815	        assert_eq!(
5816	            baseline,
5817	            drained_order([lower, higher], false),
5818	            "window state"
5819	        );
5820	        assert_eq!(baseline, drained_order([higher, lower], false), "both");
5821	        assert!(baseline.contains(&lower) && baseline.contains(&higher));
5822	    }
