5927	    /// F3: a run-queue removal requested while a tentative_pop window is live
5928	    /// (an asynchronous exec reconnect racing the daemon) must be deferred, not
5929	    /// applied through `remove_tid`'s `tentative_selection.is_none()` guard, and
5930	    /// a pending-removal thread whose `next_turns` entry is already gone must not
5931	    /// crash `are_all_quiesced`. The removal lands at the next drain.
5932	    /// ITEM 1 REGRESSION: a NON-LEADER thread is live, even though it is not a
5933	    /// kill target.
5934	    ///
5935	    /// `process_signal_targets` models `kill(2)`, whose first act is to refuse
5936	    /// anything that is not a thread-group leader. `sched_setattr(2)` and its
5937	    /// relatives resolve through `find_task_by_vpid`, which finds any live
5938	    /// task. Answering the second question with the first resolver reports
5939	    /// ESRCH for a thread that is plainly running, so the two must stay
5940	    /// distinguishable -- this test fails the moment `thread_is_live` is
5941	    /// reduced to the kill resolver.
5942	    #[test]
5943	    fn a_non_leader_thread_is_live_without_being_a_kill_target() {
5944	        let mut sched = Scheduler::new(&Config::default());
5945	        let leader = DetTid::from_raw(11);
5946	        let member = DetTid::from_raw(12);
5947	        let stranger = DetTid::from_raw(13);
5948	        sched.thread_tree.add_child(leader, leader, true);
5949	        sched.thread_tree.add_child(leader, member, false);
5950	        register_known_thread(&mut sched, leader);
5951	        register_known_thread(&mut sched, member);
5952	
5953	        assert!(sched.thread_is_live(leader), "the leader is obviously live");
5954	        assert!(
5955	            sched.thread_is_live(member),
5956	            "a non-leader thread of a live group is live; sched_setattr must reach it"
5957	        );
5958	        assert!(
5959	            !sched.thread_is_live(stranger),
5960	            "a tid that was never registered is not live"
5961	        );
5962	
5963	        // The distinction being preserved: the kill resolver still declines the
5964	        // non-leader, which is correct for kill(2) and wrong for sched_setattr.
5965	        assert!(
5966	            sched.process_signal_targets(member).is_empty(),
5967	            "kill(2) semantics: a non-leader is not a signal target, which is \
5968	             exactly why it is the wrong resolver for a tid lookup"
5969	        );
5970	        assert!(
5971	            !sched.process_signal_targets(leader).is_empty(),
5972	            "the leader is a signal target, so the fixture is wired correctly"
5973	        );
5974	    }
