6435	    /// F8 (non-committing fizzle), part 1: the branch itself, both ways.
6436	    ///
6437	    /// NEGATIVE -- the defect. A selected thread whose `next_turns` entry
6438	    /// vanished during the daemon's post-await window must abandon the turn:
6439	    /// report `SkipTurn` (it commits nothing -- steps 4-7 are bypassed) AND
6440	    /// close the tentative window `step3_peek` opened. Before the fix this
6441	    /// branch fell through to `Ok(rsrcs)`, which `bump_global_time` reads as a
6442	    /// completed turn and answers with a virtual-time advance.
6443	    /// POSITIVE -- not inert. A thread that is still registered proceeds: `Ok`,
6444	    /// with its tentative selection left open for step4 to commit. Without this
6445	    /// side an `abort_turn_if_thread_vanished` that simply always skipped would
6446	    /// pass the negative and silently stall the scheduler.
6447	    #[test]
6448	    fn a_vanished_thread_aborts_its_turn_and_a_live_one_does_not() {
6449	        let config = Config::default();
6450	        let vanishing = DetTid::from_raw(11);
6451	        let live = DetTid::from_raw(13);
6452	
6453	        let mut sched = Scheduler::new(&config);
6454	        register_known_thread(&mut sched, vanishing);
6455	        register_known_thread(&mut sched, live);
6456	        sched.runqueue_push_back(vanishing);
6457	        sched.runqueue_push_back(live);
6458	
6459	        // NEGATIVE: retire `vanishing` after its selection was tentatively
6460	        // popped, exactly as teardown does inside the post-await window.
6461	        assert_eq!(
6462	            sched.run_queue.tentative_pop_tid(vanishing),
6463	            Some(vanishing)
6464	        );
6465	        assert!(sched.run_queue.tentative_pop_in_progress());
6466	        sched.next_turns.remove(&vanishing);
6467	        assert!(
6468	            sched.abort_turn_if_thread_vanished(vanishing).is_err(),
6469	            "a turn that bypasses steps 4-7 must report SkipTurn, never success: \
6470	             reporting Ok lets bump_global_time advance virtual time for a turn \
6471	             that committed nothing"
6472	        );
6473	        assert!(
6474	            !sched.run_queue.tentative_pop_in_progress(),
6475	            "the abandoned turn must also close its tentative window"
6476	        );
6477	
6478	        // POSITIVE: a still-registered thread is untouched and proceeds to
6479	        // step4 with its selection still open to commit.
6480	        assert_eq!(sched.run_queue.tentative_pop_tid(live), Some(live));
6481	        assert!(sched.run_queue.tentative_pop_in_progress());
6482	        assert!(
6483	            sched.abort_turn_if_thread_vanished(live).is_ok(),
6484	            "a live thread's turn must proceed"
6485	        );
6486	        assert!(
6487	            sched.run_queue.tentative_pop_in_progress(),
6488	            "a proceeding turn must keep its tentative selection open for step4"
6489	        );
6490	    }
