7190	    /// A thread can hold a `WaitChild` request while ALREADY in the run queue:
7191	    /// `wake_child_waiters` re-admits a waiter without clearing its request, and
7192	    /// `step6_reenqueue` pushes a completed turn back before the guest issues
7193	    /// its next request. An earlier revision inferred "blocked" from the
7194	    /// resource and skipped the run-queue removal, so the drain pushed a
7195	    /// second copy of the thread.
7196	    ///
7197	    /// That failure is worse than it looks: `RunQueue`'s duplicate check is
7198	    /// `cfg!(debug_assertions)`, so debug builds panic with "Invariant
7199	    /// violation! Tried to add ... already present" while RELEASE builds
7200	    /// silently enqueue the thread twice and select it twice.
7201	    #[test]
7202	    fn pending_signal_does_not_double_queue_a_runnable_child_waiter() {
7203	        let mut scheduler = Scheduler::new(&Config::default());
7204	        let target = DetTid::from_raw(100);
7205	        let parent = DetPid::from_raw(100);
7206	        register_known_thread(&mut scheduler, target);
7207	        let spec = ChildWaitSpec {
7208	            selector: ChildWaitSelector::Any,
7209	            owner: None,
7210	            exit_class: ChildWaitExitClass::Sigchld,
7211	        };
7212	        let mut waiting = Resources::new(target);
7213	        waiting.insert(ResourceID::WaitChild { parent, spec }, Permission::R);
7214	        waiting.fyi("wait-child-lifecycle");
7215	        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(waiting));
7216	        // The distinguishing state: holds WaitChild AND is runnable, with no
7217	        // `child_waiters` entry -- exactly what a just-woken waiter looks like.
7218	        scheduler.runqueue_push_back(target);
7219	        assert!(scheduler.run_queue.contains_tid(target));
7220	        assert!(!scheduler.blocked.child_waiters.contains_key(&target));
7221	
7222	        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR1));
7223	        scheduler.drain_pending_cross_task_signals();
7224	
7225	        let occurrences = scheduler
7226	            .run_queue
7227	            .tids()
7228	            .filter(|tid| **tid == target)
7229	            .count();
7230	        assert_eq!(
7231	            occurrences, 1,
7232	            "the signalled child waiter must appear in the run queue exactly once"
7233	        );
7234	    }
