#[test]
fn vfork_registration_barrier_releases_deferred_failed_clone() {
    let config = Config {
        backend_defers_vfork_child_registration: true,
        ..Config::default()
    };
    let mut scheduler = Scheduler::new(&config);
    let parent = DetTid::from_raw(3);
