7914	    /// "no deadline", not a deadline. With nothing else left to run, the guest is
7915	    /// permanently blocked and must be reported as such -- never woken.
7916	    #[test]
7917	    fn indefinite_waiter_alone_is_reported_as_a_deadlock() {
7918	        let config = Config::default();
7919	        let mut scheduler = Scheduler::new(&config);
7920	        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
7921	        let initial_time = global_time.lock().unwrap().as_nanos();
7922	
7923	        scheduler
7924	            .blocked
7925	            .timed_waiters
7926	            .insert(LogicalTime::INDEFINITE, DetTid::from_raw(100));
7927	
7928	        assert!(scheduler.step2d_handle_empty_queue(&global_time).is_err());
7929	
7930	        // Asserting the verdict by value, not by catching a panic: the report is
7931	        // recorded for `sched_loop_inner` to print and exit on, so the text is
7932	        // checkable here rather than only through `#[should_panic]`.
7933	        let report = scheduler
7934	            .take_terminal_deadlock()
7935	            .expect("an indefinite waiter with nothing runnable is a terminal deadlock");
7936	        assert!(
7937	            report.contains("thread(s) waiting indefinitely"),
7938	            "unexpected report:\n{report}"
7939	        );
7940	        // Taking it is destructive, and the indefinite waiter is never woken.
7941	        assert!(scheduler.take_terminal_deadlock().is_none());
