8047	    /// The `SignalEvt` arm is the sub-case whose behaviour this change actually
8048	    /// alters, and it is reachable with no `pause` anywhere.
8049	    ///
8050	    /// `handle_timer_settime` adds a guest-supplied duration to now, and
8051	    /// `LogicalTime`'s `Add` saturates, so an absurdly far-future POSIX timer
8052	    /// (issue #219, the Java case) lands on `LogicalTime::INDEFINITE` and
8053	    /// `register_posix_timer` inserts it verbatim. Previously `step2d` popped it,
8054	    /// fast-forwarded the clock ~584 years, and dispatched to `fire_alarm`, which
8055	    /// -- unlike the `ThreadEvt` arm -- does NOT abort: it delivered a bogus
8056	    /// year-2554 signal and the guest carried on. That is now a terminal
8057	    /// deadlock, which is the faithful answer, because Linux will not fire that
8058	    /// timer either and those threads genuinely hang.
8059	    #[test]
8060	    fn saturated_posix_timer_alone_is_a_deadlock_not_a_bogus_signal() {
8061	        let config = Config::default();
8062	        let mut scheduler = Scheduler::new(&config);
8063	        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
8064	        let initial_time = global_time.lock().unwrap().as_nanos();
8065	        let process = DetPid::from_raw(100);
8066	
8067	        // The real production entry point, with the deadline a saturating add
8068	        // produces. No `pause`, no `ThreadEvt`.
8069	        scheduler.register_posix_timer(
8070	            process,
8071	            process,
8072	            7,
8073	            Some(LogicalTime::MAX - LogicalTime::from_nanos(0)),
8074	            LogicalTime::ZERO,
8075	            Signal::SIGALRM,
8076	        );
8077	        assert_eq!(
8078	            scheduler.blocked.timed_waiters.next_deadline(),
8079	            Some(LogicalTime::INDEFINITE),
8080	            "a saturated timer must land on the no-deadline sentinel"
8081	        );
8082	
8083	        assert!(scheduler.step2d_handle_empty_queue(&global_time).is_err());
8084	
8085	        let report = scheduler
8086	            .take_terminal_deadlock()
8087	            .expect("a saturated timer with nothing runnable is a terminal deadlock");
8088	        assert!(
8089	            report.contains("thread(s) waiting indefinitely"),
8090	            "unexpected report:\n{report}"
8091	        );
8092	        // The signal was NOT delivered and the clock did NOT jump to the end of
8093	        // logical time: both are what the old fast-forward did here.
8094	        assert_eq!(global_time.lock().unwrap().as_nanos(), initial_time);
8095	        assert!(scheduler.run_queue.is_empty());
8096	        assert!(!scheduler.blocked.timed_waiters.is_empty());
8097	    }
