8359	    /// The enforcement predicates that drive `hb_checkpoint`: an anchor is
8360	    /// reached at exactly its `SyscallCount` on the right thread, an AFTER anchor
8361	    /// of a Hard edge is blocked until its BEFORE anchor fires, and firing the
8362	    /// BEFORE anchor opens the gate. This mirrors the two-thread race validated
8363	    /// end-to-end (main_write < worker_write forcing A before B).
8364	    #[test]
8365	    fn hb_runtime_gate_opens_only_after_before_anchor_fires() {
8366	        let mut hb = hb_runtime(
8367	            r#"{
8368	              "version": 1,
8369	              "threads": { "main": {"dettid": 3}, "worker": {"dettid": 5} },
8370	              "events": {
8371	                "main_write":   {"thread": "main",   "syscalls": 47},
8372	                "worker_write": {"thread": "worker", "syscalls": 8}
8373	              },
8374	              "edges": [ {"before": "main_write", "after": "worker_write", "strength": "hard"} ]
8375	            }"#,
8376	        );
8377	        let main = DetTid::from_raw(3);
8378	        let worker = DetTid::from_raw(5);
8379	
8380	        // Anchors resolve to the addressed (thread, count) and nothing else.
8381	        assert_eq!(
8382	            hb.anchors_at_syscall(main, 47),
8383	            vec!["main_write".to_string()]
8384	        );
8385	        assert_eq!(
8386	            hb.anchors_at_syscall(worker, 8),
8387	            vec!["worker_write".to_string()]
8388	        );
8389	        assert!(hb.anchors_at_syscall(main, 8).is_empty());
8390	        assert!(hb.anchors_at_syscall(worker, 47).is_empty());
8391	        assert!(hb.anchors_at_syscall(worker, 7).is_empty());
8392	
8393	        // Before its gating BEFORE anchor fires, the AFTER anchor is blocked and
8394	        // the BEFORE anchor is free (it gates nothing).
8395	        assert!(hb.anchor_blocked("worker_write"));
8396	        assert!(!hb.anchor_blocked("main_write"));
8397	
8398	        // Firing the BEFORE anchor opens the gate exactly once.
8399	        assert!(hb.fired.insert("main_write".to_string()));
8400	        assert!(!hb.anchor_blocked("worker_write"));
8401	    }
