42	fn install_handler() -> Result<()> {
43	    static INSTALL: OnceLock<std::result::Result<usize, i32>> = OnceLock::new();
44	    let result = INSTALL.get_or_init(|| {
45	        // SAFETY: the supplied action storage is initialized and lives through
46	        // each call. The handler performs no work, allocation or locking.
47	        unsafe {
48	            let mut old: libc::sigaction = std::mem::zeroed();
49	            if libc::sigaction(SIGNAL, std::ptr::null(), &mut old) != 0 {
50	                return Err(std::io::Error::last_os_error()
51	                    .raw_os_error()
52	                    .unwrap_or(libc::EIO));
53	            }
54	            if old.sa_sigaction != libc::SIG_DFL {
55	                return Err(libc::EBUSY);
56	            }
57	            let mut action: libc::sigaction = std::mem::zeroed();
58	            action.sa_sigaction = interrupt as *const () as usize;
59	            libc::sigemptyset(&mut action.sa_mask);
60	            if libc::sigaction(SIGNAL, &action, std::ptr::null_mut()) != 0 {
61	                return Err(std::io::Error::last_os_error()
62	                    .raw_os_error()
63	                    .unwrap_or(libc::EIO));
64	            }
65	            // Retain the exact address passed to the kernel. In optimized
66	            // builds the linker may fold this empty handler with another empty
67	            // handler, while separate function-pointer materializations still
68	            // name distinct symbols. Re-evaluating `interrupt as usize` below
69	            // can therefore reject the disposition we just installed.
70	            Ok(action.sa_sigaction)
71	        }
72	    });
73	    let installed_handler = match result {
74	        Ok(handler) => *handler,
75	        Err(errno) => {
76	            return Err(failure(
77	                "reserve host signal 64",
78	                std::io::Error::from_raw_os_error(*errno),
79	            ));
80	        }
81	    };
82	    // A default-disposition check cannot exclude a future foreign owner. The
83	    // lifetime reservation is an embedding contract; detect a visible change
84	    // rather than silently replacing a library's handler on later entries.
85	    unsafe {
86	        let mut current: libc::sigaction = std::mem::zeroed();
87	        if libc::sigaction(SIGNAL, std::ptr::null(), &mut current) != 0 {
88	            return Err(last_error("query reserved host signal"));
89	        }
90	        if current.sa_sigaction != installed_handler {
91	            return Err(protocol_failure("reserved host signal disposition changed"));
92	        }
