97	fn only_reserved_signal() -> libc::sigset_t {
98	    // SAFETY: both libc functions receive initialized, writable sigset storage;
99	    // 64 is a valid signal number on this x86-64 Linux backend.
100	    unsafe {
101	        let mut set = std::mem::zeroed();
102	        libc::sigemptyset(&mut set);
103	        libc::sigaddset(&mut set, SIGNAL);
104	        set
105	    }
