108	fn ioctl_mask(saved: &libc::sigset_t) -> Result<[u8; 12]> {
109	    let mut bits = 0u64;
110	    for signal in 1..=64 {
111	        // SAFETY: saved is a valid libc sigset and the queried number is valid.
112	        match unsafe { libc::sigismember(saved, signal) } {
113	            0 => {}
114	            1 => bits |= 1u64 << (signal - 1),
115	            _ => return Err(last_error("read saved signal mask")),
116	        }
117	    }
118	    bits &= !(1u64 << (SIGNAL - 1));
119	    let mut bytes = [0; 12];
120	    bytes[..4].copy_from_slice(&8u32.to_ne_bytes());
121	    bytes[4..].copy_from_slice(&bits.to_ne_bytes());
122	    Ok(bytes)
123	}
